"""Retain bounded three-case clock adjudication; never alter frozen sources or prose."""
from pathlib import Path
import datetime as dt,gzip,hashlib,json
from zoneinfo import ZoneInfo

ROOT=Path('/workspace/work/july2024')
SHA=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
UTC=dt.timezone.utc
def convert(value,zone):
 return dt.datetime.fromisoformat(value).replace(tzinfo=ZoneInfo(zone)).astimezone(UTC).isoformat()
def evidence(key,url,cache,reference,precision,meaning,excerpt):
 p=ROOT/'audit_work/late_release_clock_refs'/cache
 return dict(key=key,url=url,cache_path=str(p.relative_to(ROOT)),cache_sha256=SHA(p),web_reference=reference,precision=precision,meaning=meaning,timing_excerpt=excerpt,timing_excerpt_sha256=hashlib.sha256(excerpt.encode()).hexdigest())
def main():
 refs=ROOT/'audit_work/release_guard_refs/official_timing_excerpts.json'
 retained=json.loads(refs.read_text());cpi_prior=next(x for x in retained['references']if x['key']=='japan_national_cpi_secondary')
 assert hashlib.sha256(cpi_prior['timing_excerpt_normalized'].encode()).hexdigest()==cpi_prior['excerpt_sha256']
 ev={
 'rio_asx':evidence('rio_asx','https://www.marketindex.com.au/asx/rio/announcements/rio-tinto-releases-second-quarter-production-results-3A645994','open_initial.json','turn402254view0:L28-L30','Dated secondary mirror of actual ASX issuer announcement; explicit AEST zone','The identical second-quarter production release is recorded before the report cutoff. This is stronger than inferring a clock from the issuer local calendar date.','Published: 16/07/24, 08:25am (AEST)'),
 'rio_wire':evidence('rio_wire','https://markets.financialcontent.com/kanerepublican/article/bizwire-2024-7-15-rio-tinto-releases-second-quarter-production-results','clock9.json','turn261002view1:L41-L45','Dated issuer press release syndicated via Business Wire; explicit EDT zone','The issuer production disclosure was distributed by this time, before the July16 UTC cutoff. This establishes an availability bound, not its first original publication second.','July 15, 2024 at 18:31 PM EDT'),
 'rio_primary':evidence('rio_primary','https://www.riotinto.com/news/releases/2024/rio-tinto-releases-second-quarter-production-results','clock5.json','turn378695view2:L590-L636','Primary issuer release; Australian date only, no clock','Identifies the exact quarterly production disclosure and train-collision/shipment subject. Its local date alone would be insufficient.','16 July 2024'),
 'exports_primary':evidence('exports_primary','https://www.customs.go.jp/toukei/shinbun/trade-st_e/2024/2024064e.pdf','clock10.json','turn113858view0:P0:L10-L24','Primary June provisional trade release, dated July18; minute absent from PDF header','Confirms the exact release vintage is June2024 provisional trade data. No later revised customs table was substituted.','Release July 18, 2024'),
 'exports_clock':evidence('exports_clock','https://investinglive.com/news/japan-data-june-exports-54-yy-expected-64-imports-32-yy-expected-93-20240717/','clock9.json','turn261002search5','Dated contemporaneous actual-data news item with explicit GMT; retained indexed extraction only','The June exports/imports actual-data headline is timestamped before the July18 cutoff. Direct open returned403, so this is retained search extraction, not a full original page snapshot.','17/07/2024 | 23:50 GMT'),
 'exports_calendar':evidence('exports_calendar','https://www.dlri.co.jp/files/macro/351020.pdf','target3.json','turn281479search46','Dated institutional weekly calendar for July15–19; search extraction only','The July18 June trade-statistics row has08:50, corroborating23:50UTC onJuly17 when interpreted in Japan local time. The direct PDF open returned403; this source corroborates, rather than independently certifying, actual release.','7月18日（木） 8:50 6月貿易統計'),
 'cpi_dataset':evidence('cpi_dataset','https://www.e-stat.go.jp/en/stat-search/files?cycle=1&layout=dataset&month=12040606&page=1&stat_infid=000040191571&tclass1=000001150149&tclass2val=0&toukei=00200573&tstat=000001150147&year=20240','search_targeted.json','turn183075view0:L316-L332','Primary official June2024 CPI dataset historical publication metadata','Unlike a generic current release calendar, the identified June2024 dataset itself records the historical publication date and08:30 clock. The official CPI convention explicitly identifies Japan time.','Published date and time 2024-07-19 08:30'),
 'cpi_timezone':evidence('cpi_timezone','https://www.stat.go.jp/english/data/cpi/1585.htm','clock5.json','turn378695view4:L123-L125','Primary current publication-method statement; timezone corroboration only','Identifies the CPI release clock as Japan time. Current methodological text alone is not proof of an individual2024 event; it is combined with exact dated historical metadata.','8:30 A.M. (Japan time)'),
 }
 cases=[]
 base_limits=['The frozen Google RSS date was normalized to the preceding day07UTC; it was not used as the event clock.','Connected-web historical extracts are preserved below; original contemporaneous HTML/PDF bytes and exact original Reuters headline versions were not certified.','Only the existing own-date headline premise is adjudicated. No figures, forecasts, analyst quotes, intraday cash reactions or subsequent policy commentary from this research may be added to reports.']
 definitions=[
  ('2024-07-16','n0077','Rio second-quarter iron-ore shipment miss',['rio_asx','rio_wire','rio_primary'],dict(asx=convert('2024-07-16T08:25:00','Australia/Sydney'),wire=convert('2024-07-15T18:31:00','America/New_York')),'Actual distribution timestamps support availability byJuly15 22:31UTC, more than an hour before cutoff. The own headline reports a shipment miss; the release clock does not permit aJuly16 Australian cash-session reaction.',['The issuer release supports shipments and the operational disruption; the comparison with analyst estimates comes from the existing Reuters headline, not from a newly imported issuer consensus.','Current Reuters retrieval carriesJuly16 01:16:01UTC; the current syndicated body contains an early Australian share reaction after cutoff. Neither is used to certify the original article version. Investing first-published metadata07:54PM lacks an explicit timezone in the retained extract and was not converted.']),
  ('2024-07-18','n1557','Japan June provisional export growth',['exports_primary','exports_clock','exports_calendar'],dict(local_schedule=convert('2024-07-18T08:50:00','Asia/Tokyo'),contemporaneous_actual_news='2024-07-17T23:50:00+00:00'),'Primary dated release plus explicit23:50GMT actual-data reporting support event availability ten minutes before cutoff. The calendar independently corroborates the local08:50 timing.',['The original Reuters exact headline version is not certified. The currently retrievable Reuters item is datedJuly18 02:16:31UTC; a MarketScreener syndication recordsJuly18 00:28UTC. These later retrieval/syndication times do not prove that the underlying data or an earlier wire version were unavailable, and were not treated as first publication proof.','Investing first-published metadata07:59PM has no explicit timezone in the retained extract and was not converted.']),
  ('2024-07-19','n1606','Japan June national CPI',['cpi_dataset','cpi_timezone'],dict(official_publication=convert('2024-07-19T08:30:00','Asia/Tokyo')),'Exact official historical publication metadata corroborates the already accepted dated secondary calendar:June CPI was available atJuly18 23:30UTC, thirty minutes before cutoff.',['The previously accepted Vietnam-local weekly-calendar evidence supports scheduled availability; it did not certify an original article version. The newly retained primary dataset timestamp strengthens the event-clock basis without changing the frozen schedule or feed.','The current Reuters version is datedJuly19 05:27UTC and can include later quotes/commentary. Investing metadata first-published07:37PM has no explicit timezone in the retained extract; neither timestamp is used as original pre-cutoff article certification.']),
 ]
 for date,identity,subject,keys,clocks,reason,limits in definitions:
  feedpath=ROOT/'feeds'/f'{date}.json.gz';feed=json.loads(gzip.decompress(feedpath.read_bytes()));item=next(x for x in feed['items']if x['id']==identity);cutoff=dt.datetime.fromisoformat(date).replace(tzinfo=UTC)
  assert all(dt.datetime.fromisoformat(value)<cutoff for value in clocks.values())
  reviewpath=ROOT/'audit'/f'independent_nonretail_{date}.json'
  cases.append(dict(date=date,id=identity,subject=subject,title=item['title'],rss_published_at=item['published_at'],feed_sha256=SHA(feedpath),source_item_sha256=hashlib.sha256(json.dumps(item,ensure_ascii=False,sort_keys=True,separators=(',',':')).encode()).hexdigest(),blocked_review_sha256=SHA(reviewpath),cutoff_utc=cutoff.isoformat(),clock_evidence=[ev[k]for k in keys],clock_conversions_utc=clocks,event_available_before_cutoff=True,original_reuters_article_vintage_certified=False,verdict='release_availability_supported_only',disposition='The release-clock question can be resolved for the existing own-headline completed-event premise. This is not permission to import later article wording, numbers or reactions. If exact original article-vintage certification is required beyond the accepted headline/RSS workflow, conservatively omit this exact cited premise rather than claiming that certification.',reason=reason,limits=base_limits+limits))
 cpi=cases[2];cpi['retained_prior_calendar']={**cpi_prior,'retained_reference_path':str(refs.relative_to(ROOT)),'retained_reference_sha256':SHA(refs)}
 cache=[dict(path=str(p.relative_to(ROOT)),sha256=SHA(p),bytes=p.stat().st_size)for p in sorted((ROOT/'audit_work/late_release_clock_refs').glob('*.json'))]
 result=dict(review_type='independent_bounded_three_case_release_clock_adjudication',reviewed_at_utc=dt.datetime.now(UTC).isoformat(),passed=True,scope='Release-event availability only for the three named own-date records. No report authoring, canonical publisher-version certification, frozen-source amendment or prose approval.',authoring_or_prose_approval=False,source_mutations=False,case_count=3,unresolved_event_clock_questions=0,original_article_vintages_certified=0,cases=cases,retained_tool_cache=cache,accepted_schedule_sha256=SHA(ROOT/'audit_work/july_release_schedule.json'),accepted_source_review_sha256=SHA(ROOT/'audit/independent_source_review.json'),contract_sha256=SHA(ROOT/'AUTHORING.md'),rule_interpretation='AUTHORING.md requires actual release-time assessment and permits early-local releases before UTC midnight. The accepted source workflow explicitly preserves canonical publisher-vintage limits. Dated event-clock corroboration resolves a release-availability question; it does not silently resolve an article-version question. The existing dated secondary CPI calendar was sufficient for bounded scheduled-availability support under that workflow; exact official historical metadata now corroborates it.',retention='JSON caches contain actual connected-web tool responses and source/ref metadata, not original full HTTP response bytes. Failed/blocked opens remain recorded; no alternate network route was used to bypass policy. Irrelevant search results, current sidebars, later revisions, intraday reactions and later comments are excluded from the adjudication.',review_script_sha256=SHA(Path(__file__)))
 path=ROOT/'audit/independent_late_release_clock_review.json';path.write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n');print(json.dumps(dict(path=str(path),sha256=SHA(path),cases=3,event_clocks_supported=3,original_article_vintages_certified=0,source_mutations=False),indent=2))
if __name__=='__main__':main()
